"""S2 spatio-temporal scheduler + router + cin generator (netlist-authoritative).

Resources: PE cfg blocks (pes_N via pe_blk_map), GIB mux tables (netlist_gibs),
inter-GIB tracks + PE/IOB pin maps (netlist_wires), GPE operand muxes
(netlist_pes). Scheduling: ASAP ctx assignment, slot = ctx%2, per-slot config
streams (dual-slot rotation-transparent when identical).
"""
import json, os

D = os.path.dirname(os.path.abspath(__file__))
# netlist tables live in tools/netlist (generated by parse_*.py from top.v);
# S2_NETLIST overrides the location for experiments on another build.
NET = os.environ.get('S2_NETLIST') or os.path.abspath(os.path.join(D, '..', 'netlist'))
GIBS = json.load(open(os.path.join(NET, 'netlist_gibs.json')))
WIRES = json.load(open(os.path.join(NET, 'netlist_wires.json')))
PES = json.load(open(os.path.join(NET, 'netlist_pes.json')))
PEBLK = {int(k): v for k, v in json.load(open(os.path.join(NET, 'pe_blk_map.json'))).items()}
INST2BLK = {v['inst']: int(k) for k, v in GIBS.items()}
REGS = json.load(open(os.path.join(NET, 'netlist_regs.json')))
REG_OF = {v['inst']: set(v['reg']) for v in REGS.values()}

def is_reg(inst, port):
    """port is a clocked GIB output (Interconnect.scala 520) vs combinational (522)"""
    return port in REG_OF.get(inst, ())

def path_delay(path):
    """cycles a route adds = number of REGISTERED otrack hops, not hop count"""
    return sum(1 for ent in path if is_reg(ent[0], ent[1]))

OPC = {'PASS': 0, 'ADD': 1, 'SUB': 2, 'MUL': 3}

def gpe_operand_mux(inst, operand, in_p):
    """(lo, slot, width) selecting io_in_<p> on operand mux <operand>."""
    info = _op_mux(inst, operand)
    want = 'io_in_%d' % in_p
    if want in info['srcs']:
        hi, lo = info['cfg']
        return lo, info['srcs'].index(want), hi - lo + 1
    return None

def gpe_const_slot(inst, operand):
    info = _op_mux(inst, operand)
    hi, lo = info['cfg']
    return lo, info['srcs'].index('cfgOut[31:0]'), hi - lo + 1

def _op_mux(inst, operand):
    want = 'rdu_io_in_0' if operand == 0 else 'rdu_io_in_1'
    return PES[str(inst)]['mux'][want]

class Router:
    def __init__(self):
        self.used = set()   # (gib, dstport) muxes already assigned

    def preds(self, gib, port):
        g = GIBS[str(INST2BLK[gib])]
        if port in g['mux']:
            info = g['mux'][port]
            if info['cfg'] is None:
                return
            for i, s in enumerate(info['srcs']):
                yield ('mux', gib, port, i, s)
        elif port in g['direct']:
            yield ('direct', gib, port, None, g['direct'][port])
        if port.startswith('itrack'):
            for (dg, dp, sg, sp) in WIRES['tracks']:
                if dg == gib and dp == port:
                    yield ('track', gib, port, None, (sg, sp))

    def route(self, src_pe, dst_pe, in_p, avoid=(), occ=()):
        """BFS from dst PE's input pin back to src PE's opin.
        `occ` = (gib, port) nodes already claimed by another path: a wire/track can
        carry only one source, so sharing one silently aliases two values.
        Returns list of (gib, dstport, src_index|None, srcport)."""
        tgt = WIRES['pe_in'][str(dst_pe)][str(in_p)]  # [gib, ipin]
        start = (tgt[0], tgt[1])
        terms = set((g, p) for g, p in WIRES['pe_out'][str(src_pe)])
        # BFS over (gib, port); visited = set
        from collections import deque
        q = deque([(start, [])])
        seen = {start}
        while q:
            (g, p), path = q.popleft()
            if (g, p) in terms and path:
                return path
            if path and (g, p) in occ:
                continue
            for kind, gib, dstport, idx, src in self.preds(g, p):
                if kind == 'mux':
                    node = (gib, src)
                    if node in seen or (gib, dstport) in avoid:
                        continue
                    seen.add(node)
                    q.append((node, path + [(gib, dstport, idx, src)]))
                elif kind == 'direct':
                    node = (gib, src)
                    if node in seen:
                        continue
                    seen.add(node)
                    q.append((node, path + [(gib, dstport, None, src)]))
                elif kind == 'track':
                    sg, sp = src
                    node = (sg, sp)
                    if node in seen:
                        continue
                    seen.add(node)
                    q.append((node, path + [(gib, dstport, None, (sg, sp))]))
        return None
